#!/usr/bin/env bash
cd "$(dirname "$0")/.." || exit 2   # the repo root, so this runs from any directory
# GENERATED by tools/gen-rosters.sh - edit that, then regenerate. A gate checks.
#
# The gate ROSTER for this repo: the one tracked list of checks that must pass
# before a push. Ships with ONE gate registered, the unfilled-holes check on
# CLAUDE.md, so a repo that has been set up but not authored cannot push
# without saying so. Add this repo's own.
#
# USAGE
#   bash scripts/gates.sh           # run every gate, then summarise
#   bash scripts/gates.sh --quiet   # silent on success; failures always speak
#
# EXIT STATUS
#   0  every gate passed.
#   1  at least one gate FAILED. A real finding; the caller should block.
#   2  at least one gate could not RUN, and nothing failed. NOT a finding.
#      Also: nothing registered. A push with no checks is a blind spot.
#
# The exit status is a verdict, not a finding count.
#
# WHEN A GATE "could not run"
#   Only when a tool named by bare name on its run_gate line is not on PATH.
#   See run_gate. Everything else nonzero is a finding, on purpose: a check
#   that is missing, crashing, or misconfigured must block a push, not wave it
#   through.
#
# The hook runs this on the WORKING TREE at push time, not on the pushed
# commit. Deliberate: this tier has seconds, and a scratch checkout with a
# fresh install does not fit in them. The ship tier checks the exact commit.

set -uo pipefail

QUIET=0
[ "${1:-}" = "--quiet" ] && QUIET=1

PASS=0; FAIL=0; SKIP=0
FAILED_GATES=""; SKIPPED_GATES=""

say() { [ "$QUIET" = "1" ] || printf '%s\n' "$*"; }

# run_gate [--needs tool[,tool...]] <name> <command...>
#
# SKIP (exit 2 from the roster) happens in exactly one case: a tool named on
# this line by BARE NAME is not on PATH. That is <command> itself, plus
# anything declared with --needs. A bare name is the machine's; a PATH (anything
# containing a slash, like ./scripts/check.sh) is the repo's, and a missing one
# is a finding, never a skip. Nothing a gate does once it is running can turn
# a failure into a skip either: exit 2 from a found command is a finding, and
# so is exit 127, which is what `bash` returns when the SCRIPT it was handed is
# missing. A deleted or renamed check must block, not warn.
run_gate() {
  needs=""
  if [ "${1:-}" = "--needs" ]; then needs="$2"; shift 2; fi
  name="$1"; shift
  for t in $(printf '%s' "$needs" | tr ',' ' ') "$1"; do
    case "$t" in
      */*)
        if [ ! -e "$t" ]; then
          FAIL=$((FAIL+1)); FAILED_GATES="$FAILED_GATES $name"
          printf '  FAIL  %s (%s does not exist - deleted or renamed?)\n' "$name" "$t" >&2
          return
        fi ;;
      *)
        if ! command -v "$t" >/dev/null 2>&1; then
          SKIP=$((SKIP+1)); SKIPPED_GATES="$SKIPPED_GATES $name"
          printf '  SKIP  %s (%s is not on PATH)\n' "$name" "$t" >&2
          return
        fi ;;
    esac
  done
  out=$("$@" 2>&1); rc=$?
  if [ "$rc" = "0" ]; then
    PASS=$((PASS+1)); say "  ok    $name"
  else
    FAIL=$((FAIL+1)); FAILED_GATES="$FAILED_GATES $name"
    hint=""; [ "$rc" = "127" ] && hint=" - a file this gate runs is missing?"
    printf '  FAIL  %s (exit %s%s)\n' "$name" "$rc" "$hint" >&2
    [ -n "$out" ] && printf '%s\n' "$out" >&2
  fi
}

say "gates:"
EMPTY_MSG="summary: no gates registered. A push with no checks is a blind spot, not a pass. Register this repo's checks in scripts/gates.sh."

# The frame's holes read <like this>. Code spans and fenced blocks are ignored,
# so a CLAUDE.md that mentions `<tag>` in backticks or shows HTML in a fence
# does not trip it. A missing CLAUDE.md is a finding: /kit step 3 creates it.
unfilled_holes() {
  [ -f "$1" ] || { printf '%s is missing. Copy the frame: /kit step 3.\n' "$1"; return 1; }
  hits=$(awk '/^```/{f=!f; next} !f' "$1" | sed 's/`[^`]*`//g' | grep -nE '<[A-Za-z*]')
  [ -z "$hits" ] && return 0
  printf 'unfilled holes in %s:\n%s\n' "$1" "$hits"; return 1
}

# ---------------------------------------------------------------------------
# REGISTER THIS REPO'S GATES BETWEEN THE MARKERS.
#
# A gate earns its slot by failing a command when the invariant is violated.
# A check nothing runs is a convention, and conventions do not fail.
#
# Examples:
#
#   run_gate "unit tests"   bash scripts/run_unit_tests.sh
#   run_gate "typecheck"    npm run --silent typecheck
#   run_gate --needs python3 "links" python3 scripts/linkcheck.py
#
# Keep the list short. Every gate runs on every push, and a slow roster gets
# overridden, which is worse than a small one.
# ---------------------------------------------------------------------------
# --- checks begin ---
run_gate "CLAUDE.md has no unfilled holes" unfilled_holes CLAUDE.md
# --- checks end ---

TOTAL=$((PASS+FAIL+SKIP))
if [ "$TOTAL" = "0" ]; then
  say "  (none registered)"
  printf '%s\n' "$EMPTY_MSG" >&2
  exit 2
fi

say "summary: $PASS passed, $FAIL failed, $SKIP could not run"

if [ "$FAIL" -gt 0 ]; then
  printf 'FAILED:%s\n' "$FAILED_GATES" >&2
  exit 1
fi
if [ "$SKIP" -gt 0 ]; then
  printf 'COULD NOT RUN:%s\n' "$SKIPPED_GATES" >&2
  exit 2
fi
exit 0
